using System.Globalization;
using System.Net;
using System.Text;
using System.Text.Json;
using System.Text.RegularExpressions;
using HtmlAgilityPack;
namespace TsRecommend;
record Show(string Key,int ServiceId,int EventId,string Station,string Title,string Description,DateTimeOffset Start,DateTimeOffset End,Dictionary<int,string> Actions){public string GenreColor{get;init;}="";}
record Booking(string Id,string Title,string Station,int ServiceId,int EventId,DateTimeOffset Start,DateTimeOffset End,int Device,bool Manual,bool Enabled,bool Repeating,Dictionary<string,string> Fields);
record Tuner(int Device,HashSet<string> Stations);
record Taste(string Text,double Weight);
record Pick(Show Show,int Device,double Score,string SearchWord,string Reason);
record Removal(Booking Booking,string KeepId,string Reason);
record Plan(List<Pick> Add,List<Removal> Remove,int Programs,int Existing,int Preferences,DateTimeOffset Created);
sealed class State {public DateTimeOffset? NextDue{get;set;} public DateTimeOffset? CycleStarted{get;set;}public int AddedInCycle{get;set;} public List<string> Attempted{get;set;}=[];}
static class Data {
 public static readonly Encoding Cp932=Encoding.GetEncoding(932);
 public static string Text(HtmlNode n)=>WebUtility.HtmlDecode(n.InnerText).Replace("\0","").Trim();
 public static string Clean(string s)=>Regex.Replace(s.Normalize(NormalizationForm.FormKC),@"\s+"," ").Trim();
 public static string Norm(string s)=>Regex.Replace(Regex.Replace(Clean(s),@"\[(?:再|字|デ|解|二|多|新|終|無料)\]", ""),@"[\s\p{P}\p{S}]", "").ToLowerInvariant();
 public static string StationKey(string station){var key=Clean(station).Replace(" ","");return key switch {"テレビ朝日" or "テレ朝"=>"テレビ朝日","NHKEテレ" or "NHK Eテレ" or "Eテレ"=>"Eテレ","日本テレビ" or "日テレ"=>"日本テレビ","テレビ東京" or "テレ東"=>"テレビ東京","フジテレビ" or "フジ"=>"フジテレビ","TOKYOMX1" or "TOKYOMX" or "MX1" or "MX"=>"TOKYOMX",_=>key};}
 public static bool SameStation(string left,string right)=>StationKey(left)==StationKey(right);
 public static List<Booking> Bookings(string path){var records=new List<Dictionary<string,string>>();Dictionary<string,string>? current=null;foreach(var line in File.ReadLines(path,Cp932)){var m=Regex.Match(line,@"^\d+ ([A-Z0-9-]+) (.*)$");if(!m.Success)continue;string k=m.Groups[1].Value;if(k=="START"){current=new(StringComparer.OrdinalIgnoreCase);records.Add(current);}if(current!=null)current[k]=m.Groups[2].Value;}return records.Where(r=>r.ContainsKey("UNIQID")&&r.ContainsKey("END")).Select(r=>{long N(string k)=>long.TryParse(r.GetValueOrDefault(k),out var n)?n:0;return new Booking(r["UNIQID"],r.GetValueOrDefault("TITLE", ""),r.GetValueOrDefault("STATION", ""),(int)N("SERVICEID"),(int)N("EVENTID"),DateTimeOffset.FromUnixTimeSeconds(N("START")),DateTimeOffset.FromUnixTimeSeconds(N("END")),(int)N("DEVNO"),N("SEARCHID")==0,N("VALIDATE")==1,N("REPEAT")!=0,r);}).ToList();}
 public static (List<Tuner> Tuners,Dictionary<int,string> Stations) Tuners(string path){var sections=new Dictionary<string,Dictionary<string,string>>(StringComparer.OrdinalIgnoreCase);Dictionary<string,string>? current=null;foreach(var raw in File.ReadLines(path,Cp932)){var line=raw.Trim();if(line.StartsWith('[')&&line.EndsWith(']')){current=new(StringComparer.OrdinalIgnoreCase);sections[line[1..^1]]=current;}else{int sep=line.IndexOf('=');if(current!=null&&sep>0)current[line[..sep]]=line[(sep+1)..];}}var tuners=new List<Tuner>();var stations=new Dictionary<int,string>();foreach(var item in sections){var m=Regex.Match(item.Key,@"^TUNER(\d+)$");if(!m.Success)continue;int number=int.Parse(m.Groups[1].Value);if(!sections.TryGetValue($"TUNER{number} SERVICE",out var channels))continue;var supported=new HashSet<string>();foreach(var ch in channels){if(int.TryParse(ch.Value,out int id)){stations[id]=ch.Key;supported.Add(ch.Key);}}if(!string.IsNullOrWhiteSpace(item.Value.GetValueOrDefault("APPNAME1")))tuners.Add(new Tuner(number+4,supported));}return(tuners,stations);}
 public static List<Taste> Preferences(string html,List<Booking> history){var doc=new HtmlAgilityPack.HtmlDocument();doc.LoadHtml(html);var list=new List<Taste>();foreach(var row in doc.DocumentNode.SelectNodes("//tr")??new HtmlNodeCollection(null)){var cells=row.SelectNodes("./td");if(cells?.Count!=14)continue;var link=cells[13].SelectSingleNode(".//a[contains(@href,'kwl?i=')]");if(link==null)continue;var enabled=cells[1].InnerText.Contains('○');if(!enabled)continue;string phrase=Clean(Text(cells[13]));if(phrase.Length>1)list.Add(new Taste(phrase,1.2));}foreach(var b in history.Where(b=>b.Enabled))if(b.Title.Length>2)list.Add(new Taste(Clean(b.Title),b.Manual?1.25:1));return list.DistinctBy(p=>p.Text).ToList();}
 public static Dictionary<string,string> Query(string href){int q=href.IndexOf('?');if(q<0)return[];return href[(q+1)..].Split('#')[0].Split('&',StringSplitOptions.RemoveEmptyEntries).Select(p=>p.Split('=',2)).GroupBy(p=>p[0]).ToDictionary(g=>g.Key,g=>WebUtility.UrlDecode(g.Last().ElementAtOrDefault(1)??""));}
 public static List<Show> Guide(string html,int offset,DateTimeOffset broadcastDay,Dictionary<int,string> stations){var doc=new HtmlAgilityPack.HtmlDocument();doc.LoadHtml(html);var output=new List<Show>();var cells=doc.DocumentNode.SelectNodes("//td[@rowspan]")??new HtmlNodeCollection(null);foreach(var cell in cells){var links=cell.SelectNodes(".//a[@href]")??new HtmlNodeCollection(null);var actions=new Dictionary<int,string>();int sid=0,eid=0;foreach(var link in links){var href=WebUtility.HtmlDecode(link.GetAttributeValue("href",""));var q=Query(href);if(q.GetValueOrDefault("r") is not ("1" or "6")||!q.ContainsKey("c")||!q.ContainsKey("e")||!q.ContainsKey("d"))continue;if(!int.TryParse(q["c"],out sid)||!int.TryParse(q["e"],out eid)||!int.TryParse(q["d"],out int device))continue;if(q.GetValueOrDefault("r")=="1")actions[device]=href;}if(sid==0||!stations.TryGetValue(sid,out var station))continue;var titleLink=cell.SelectSingleNode(".//a[contains(@href,'kws?tsea=1')]")??cell.SelectSingleNode(".//a[starts-with(@href,'reg?i=')]");if(titleLink==null)continue;string title=Text(titleLink).Replace("\u200b","");var match=(cell.SelectNodes(".//small/b")??new HtmlNodeCollection(null)).Select(n=>Regex.Match(Text(n),@"^(\d{1,2}):(\d{2})(?:～\d{1,2}:\d{2})?")).FirstOrDefault(m=>m.Success);if(match==null)continue;if(!match.Success)continue;var row=cell.ParentNode;var tbody=row.ParentNode;var rows=tbody.SelectNodes("./tr");if(rows==null)continue;int first=rows.ToList().FindIndex(r=>r.SelectSingleNode("./td[@rowspan]")!=null);int index=rows.IndexOf(row);if(first<0||index<first)continue;var slot=broadcastDay.AddHours(4+offset).AddMinutes(index-first);var start=new DateTimeOffset(slot.Year,slot.Month,slot.Day,0,0,0,slot.Offset).AddHours(int.Parse(match.Groups[1].Value)).AddMinutes(int.Parse(match.Groups[2].Value));if(start>slot.AddMinutes(2))start=start.AddDays(-1);var end=slot.AddMinutes(cell.GetAttributeValue("rowspan",0));if(end<=start||end-start>TimeSpan.FromHours(12))continue;var detailNode=cell.SelectSingleNode(".//small/small");string desc=detailNode==null?"":Clean(Text(detailNode));output.Add(new Show($"{sid}/{eid}/{start.ToUnixTimeSeconds()}",sid,eid,station,Clean(title),desc,start,end,actions){GenreColor=cell.GetAttributeValue("bgcolor","")});}return output;}
 public static Dictionary<string,string> Form(string html,string? submit=null){var doc=new HtmlAgilityPack.HtmlDocument();doc.LoadHtml(html);var form=doc.DocumentNode.SelectSingleNode("//form[@name='regsch']")??throw new Exception("予約フォームが見つかりません。");if((doc.DocumentNode.SelectNodes("//form")?.Count??0)!=1)throw new Exception("予約フォームが複数あるため変更を中止しました。");var values=new Dictionary<string,string>();foreach(var node in doc.DocumentNode.SelectNodes("//input[@name]|//select[@name]|//textarea[@name]")??new HtmlNodeCollection(null)){string name=node.GetAttributeValue("name","");if(node.Name=="select"){var option=node.SelectSingleNode("./option[@selected]")??node.SelectSingleNode("./option");if(option!=null)values[name]=WebUtility.HtmlDecode(option.GetAttributeValue("value",Text(option)));continue;}if(node.Name=="textarea"){values[name]=Text(node);continue;}string type=node.GetAttributeValue("type","text").ToLowerInvariant();if(type is "checkbox" or "radio" && !node.Attributes.Contains("checked"))continue;if(type is "submit" or "button"){if(submit!=null&&node.GetAttributeValue("value","").Contains(submit))values[name]=WebUtility.HtmlDecode(node.GetAttributeValue("value",""));continue;}values[name]=WebUtility.HtmlDecode(node.GetAttributeValue("value",""));}return values;}
 public static string Encode(string value)=>string.Concat(Cp932.GetBytes(value).Select(b=>(b>=65&&b<=90)||(b>=97&&b<=122)||(b>=48&&b<=57)||b is 45 or 46 or 95 or 126?((char)b).ToString():"%"+b.ToString("X2")));
}
sealed class Ranker {
 readonly List<Taste> tastes;readonly List<(string Positive,string Negative)> exclusions=[];readonly Dictionary<string,double> idf;readonly List<(Taste Taste,Dictionary<string,double> Vector)> profile;
 static readonly string[] Generic=["ニュース","スペシャル","ミュージック","ドキュメント","ドキュメンタリー","テレビ","番組","放送","再放送","特別番組","特集","日本","世界","サンデー","マンデー","サタデー","フライデー","クション","ステーション","キャスター"]; static readonly HashSet<string> Stop=new(["です","ます","番組","放送","今回","今日","特集","登場","紹介","テレビ","こちら","という","について","から","まで","その","この"]);
 public Ranker(List<Taste> items){foreach(var item in items){var negative=Regex.Match(item.Text,@"^(.*?)\s+not\s+(.+)$",RegexOptions.IgnoreCase);if(negative.Success)exclusions.Add((negative.Groups[1].Value,negative.Groups[2].Value));}items=items.Select(t=>t with{Text=Regex.Replace(t.Text,@"\s+not\s+.+$","",RegexOptions.IgnoreCase)}).ToList();tastes=items;var all=items.Select(t=>Features(t.Text)).ToList();var df=new Dictionary<string,int>();foreach(var a in all)foreach(var term in a.Keys)df[term]=df.GetValueOrDefault(term)+1;idf=df.ToDictionary(p=>p.Key,p=>Math.Log((items.Count+1d)/(p.Value+1))+1);profile=items.Select((t,i)=>(t,Vector(all[i]))).ToList();}
 static Dictionary<string,double> Features(string text){var d=new Dictionary<string,double>();foreach(Match m in Regex.Matches(Data.Clean(text).ToLowerInvariant(),@"[\p{L}\p{Nd}]+")){var s=m.Value;if(Regex.IsMatch(s,@"^[a-z0-9]+$")){if(s.Length>1)d[s]=d.GetValueOrDefault(s)+1;continue;}for(int n=2;n<=Math.Min(4,s.Length);n++)for(int i=0;i+n<=s.Length;i++){var term=s.Substring(i,n);if(!Stop.Contains(term)&&!Generic.Any(g=>g.Contains(term,StringComparison.OrdinalIgnoreCase)))d[term]=d.GetValueOrDefault(term)+1;}}return d;}
 Dictionary<string,double> Vector(Dictionary<string,double> features){var d=features.ToDictionary(p=>p.Key,p=>(1+Math.Log(p.Value))*idf.GetValueOrDefault(p.Key,Math.Log(tastes.Count+1d)+1));double norm=Math.Sqrt(d.Values.Sum(v=>v*v));return norm>0?d.ToDictionary(p=>p.Key,p=>p.Value/norm):d;}
 public (double Score,string Word,string Reason) Score(Show show){if(profile.Count==0)return(0,"","");if((show.End-show.Start).TotalMinutes<10&&!tastes.Any(t=>Data.Clean(t.Text).Length>=4&&show.Title.Contains(Data.Clean(t.Text),StringComparison.OrdinalIgnoreCase)))return(0,"","");if(Regex.IsMatch(Data.Clean(show.Title),@"^(?:\[.\])*ニュース(?:\(.*?\))?(?:\s*\[.\])*$")&&!tastes.Any(t=>Data.Norm(t.Text)=="ニュース"))return(0,"","");foreach(var ex in exclusions){try{if(ex.Positive.Split(" ",StringSplitOptions.RemoveEmptyEntries).Any(w=>show.Title.Contains(w,StringComparison.OrdinalIgnoreCase))&&Regex.IsMatch(show.Title,ex.Negative,RegexOptions.IgnoreCase,TimeSpan.FromMilliseconds(50)))return(0,"","");}catch(ArgumentException){}catch(RegexMatchTimeoutException){return(0,"","");}}if(Regex.IsMatch(show.Title,@"(?:PR|ＰＲ)(?:\s|$|[\[])|予告|番組紹介|番組宣伝",RegexOptions.IgnoreCase))return(0,"","");var v=Vector(Features(show.Title+" "+show.Title+" "+show.Description));var matches=profile.Where(p=>(p.Vector.Keys.Any(term=>term.Length>=4&&v.ContainsKey(term))||p.Vector.Keys.Count(term=>term.Length>=3&&v.ContainsKey(term))>=2)||(Data.Norm(p.Taste.Text).Length is >=2 and <=3&&Data.Norm(show.Title).Contains(Data.Norm(p.Taste.Text)))).Select(p=>(p.Taste,Similarity:v.Sum(f=>f.Value*p.Vector.GetValueOrDefault(f.Key))*p.Taste.Weight)).OrderByDescending(p=>p.Similarity).Take(3).ToList();if(matches.Count==0)return(0,"","");double score=matches[0].Similarity;string word=matches[0].Taste.Text;if(Regex.IsMatch(show.Title,"通販|ショッピング|テレビショッピング|放送休止|番組情報|番組表|番組PR")&&!tastes.Any(t=>Data.Norm(t.Text)==Data.Norm(show.Title)))return(0,"","");return(score,word,$"検索条件・予約履歴「{word}」との類似度 {score:F2}（PC内で計算）。");}
}
static class Planner {
 public static bool HasEpisodeDetail(string title){string clean=Regex.Replace(Data.Clean(title),@"\[(?:再|字|デ|解|二|多|新|終|無料)\]","").Trim();if(Regex.IsMatch(clean,"[「『].{4,}[」』]|第[0-9一二三四五六七八九十]+[話回]|#[0-9]+"))return true;var bracket=Regex.Match(clean,"【.{4,}】");return bracket.Success&&Data.Norm(clean.Remove(bracket.Index,bracket.Length)).Length>=6;}
 public static string EpisodeKey(Show show)=>HasEpisodeDetail(show.Title)?"episode:"+Data.Norm(show.Title):show.Key; public static bool SameEpisode(string titleA,string descA,string titleB,string descB){string a=Data.Norm(titleA),b=Data.Norm(titleB);if(a!=b)return false;if(a.Length<6)return false;bool detail=HasEpisodeDetail(titleA);return detail||(Data.Norm(descA).Length>=30&&Data.Norm(descA)==Data.Norm(descB)&&Regex.IsMatch(descA,"[「『].{6,}[」』]|第[0-9一二三四五六七八九十]+[話回]"));}
 public static bool SameBroadcast(Show p,Booking b)=>p.ServiceId==b.ServiceId&&Math.Abs((p.Start-b.Start).TotalSeconds)<90;
 public static int? FreeDevice(Show show,List<Tuner> tuners,IEnumerable<Booking> existing,IEnumerable<Pick> chosen){foreach(var t in tuners.Where(t=>t.Stations.Any(station=>Data.SameStation(station,show.Station))&&show.Actions.ContainsKey(t.Device))){bool clash=existing.Any(b=>b.Enabled&&(b.Device==t.Device||!tuners.Any(x=>x.Device==b.Device))&&b.Start.AddSeconds(-120)<show.End.AddSeconds(30)&&b.End.AddSeconds(30)>show.Start.AddSeconds(-120));if(!clash&&!chosen.Any(p=>p.Device==t.Device&&p.Show.Start.AddSeconds(-120)<show.End.AddSeconds(30)&&p.Show.End.AddSeconds(30)>show.Start.AddSeconds(-120)))return t.Device;}return null;}
 public static Plan Make(List<Show> guide,List<Booking> bookings,List<Taste> tastes,List<Tuner> tuners,DateTimeOffset now,int cap=20){var ranker=new Ranker(tastes);var active=bookings.Where(b=>b.Enabled&&b.End>now).ToList();var removals=new List<Removal>();var protectedIds=new HashSet<string>();foreach(var b in active.OrderBy(b=>b.Manual?0:1).ThenBy(b=>b.Start)){if(b.Start<=now.AddMinutes(15)||b.Repeating||protectedIds.Contains(b.Id))continue;var duplicate=active.Where(x=>x.Id!=b.Id&&x.Start>now.AddMinutes(15)&&!x.Repeating&&SameEpisode(b.Title,b.Fields.GetValueOrDefault("SUBTITLE",""),x.Title,x.Fields.GetValueOrDefault("SUBTITLE",""))).OrderBy(x=>x.Manual?0:1).ThenBy(x=>x.Start).FirstOrDefault();if(duplicate==null)continue;if(b.Manual){protectedIds.Add(b.Id);continue;}var keep=duplicate.Manual?duplicate:new[]{b,duplicate}.OrderBy(x=>x.Start).First();if(keep.Id==b.Id){protectedIds.Add(b.Id);continue;}if(removals.Any(r=>r.Booking.Id==keep.Id))continue;removals.Add(new Removal(b,keep.Id,"同じ回と確認できる番組名・内容の重複。手動予約を優先して保持。"));protectedIds.Add(keep.Id);}
 // Do not assume deletions have succeeded while calculating capacity.
 var selected=new List<Pick>();var ranked=guide.Where(p=>p.Start>now.AddMinutes(15)&&p.Start<now.AddDays(6)&&p.End>p.Start&&!active.Any(b=>SameBroadcast(p,b)||SameEpisode(p.Title,p.Description,b.Title,b.Fields.GetValueOrDefault("SUBTITLE","")))).Select(p=>(Show:p,Rank:ranker.Score(p))).Where(x=>x.Rank.Score>=0.22).GroupBy(x=>EpisodeKey(x.Show)).SelectMany(group=>group.Select(x=>(x.Show,Rank:(Score:group.Max(g=>g.Rank.Score),x.Rank.Word,x.Rank.Reason)))).OrderByDescending(x=>x.Rank.Score).ThenBy(x=>active.Count(b=>b.Start<x.Show.End&&b.End>x.Show.Start)).ThenBy(x=>x.Show.Start);
 var remaining=ranked.ToList();while(remaining.Count>0&&selected.Count<Math.Min(20,cap)){var item=remaining.OrderByDescending(x=>x.Rank.Score/(1+0.45*selected.Count(p=>p.SearchWord==x.Rank.Word))).First();remaining.Remove(item);if(selected.Any(p=>SameEpisode(p.Show.Title,p.Show.Description,item.Show.Title,item.Show.Description)))continue;var device=FreeDevice(item.Show,tuners,active,selected);if(device==null)continue;int busy=active.Count(b=>b.Start<item.Show.End&&b.End>item.Show.Start);selected.Add(new Pick(item.Show,device.Value,item.Rank.Score,item.Rank.Word,item.Rank.Reason+$" この時間帯の既存予約 {busy} 件、空きチューナー{device.Value-4}で録画。"));}return new Plan(selected,removals,guide.Count,bookings.Count,tastes.Count,now);}
}







